284	pub fn load_file(path: &Path) -> Vec<Case> {
285	    std::fs::read_to_string(path)
286	        .unwrap_or_else(|e| panic!("{}: {e}", path.display()))
287	        .lines()
288	        .filter(|l| !l.is_empty())
289	        .map(parse_case)
290	        .collect()
291	}
