146	/// What the kernel published for a target.
147	pub fn observe(
148	    target: Target,
149	    rows: &BTreeMap<QuantityId, PublishedRow>,
150	    model: &Model,
151	) -> Observed {
152	    let unavailable = |e: String| Observed::Unavailable(e);
153	    match target {
154	        Target::StructuralZero => Observed::StructuralZero,
155	        Target::BendingEnd { .. } | Target::BendingStation(_) => {
156	            let ids = sources(target);
157	            match (value_of(rows, ids[0]), value_of(rows, ids[1])) {
158	                (Ok(y), Ok(z)) => Observed::Magnitude(y, z),
159	                (Err(e), _) | (_, Err(e)) => unavailable(e),
160	            }
161	        }
162	        Target::Twist(m) | Target::Extension(m) => {
163	            let (kt, ka) = member_coefficients(model, m);
164	            match value_of(rows, sources(target)[0]) {
165	                Ok(v) => Observed::Value(if matches!(target, Target::Twist(_)) {
166	                    v / kt
167	                } else {
168	                    v / ka
169	                }),
170	                Err(e) => unavailable(e),
171	            }
172	        }
173	        _ => match value_of(rows, sources(target)[0]) {
174	            Ok(v) => Observed::Value(v),
175	            Err(e) => unavailable(e),
176	        },
177	    }
178	}
