 889	    pub(crate) fn combination(operands: &[(f64, &CasePrep)]) -> Result<Self, LedgerRefusal> {
 890	        let sources: Vec<(f64, &PrimitiveSource)> =
 891	            operands.iter().map(|(c, p)| (*c, &p.source)).collect();
 892	        let ledger = RetainedLedger::combined(&sources)?;
 893	        let first = &operands[0].1.source;
 894	        let prescribed = first
 895	            .constraints()
 896	            .iter()
 897	            .map(|c| {
 898	                let g = c.dof.global();
 899	                let terms = sources
 900	                    .iter()
 901	                    .map(|(factor, s)| (*factor, s.constraint(g).unwrap_or(0.0)))
 902	                    .collect();
 903	                (g, terms)
 904	            })
 905	            .collect();
 906	        let mut identity = b"K4CMB\x01".to_vec();
 907	        put_u32(&mut identity, operands.len() as u32);
 908	        for (factor, prep) in operands {
 909	            put_u64(&mut identity, factor.to_bits());
 910	            put_u32(&mut identity, prep.identity.len() as u32);
 911	            identity.extend_from_slice(&prep.identity);
 912	        }
 913	        let factors = operands.iter().map(|o| o.0).collect();
 914	        Self::with(first.clone(), ledger, prescribed, factors, identity)
 915	    }
