 949	    /// rounded twice). A case's single binary64 value publishes unchanged.
 950	    fn publish_prescribed(&self, values: &mut [Binary64Outcome]) {
 951	        for (meta, value) in self.layout.iter().zip(values.iter_mut()) {
 952	            let (true, QuantityId::Displacement(dof)) = (meta.input_derived, meta.id) else {
