 963	    /// the exact sum of its terms c·v, rounded once.
 964	    fn prescribed_at<const L: usize>(
 965	        &self,
 966	        ctx: &mut WideContext<L>,
 967	        sum: &mut ExactWideSum,
 968	        u: &mut [Wide<L>],
 969	    ) -> Result<(), AttemptStop>
