 987	/// Σ c·v over binary64 pairs, rounded once to binary64 with its outcome: the
 988	/// exact accumulator's single rounding; an exact zero is +0.0; a nonzero sum
 989	/// that rounds to zero is `Underflow`, one beyond the range `Overflow`.
 990	fn exact_publication(terms: &[(f64, f64)]) -> Binary64Outcome {
 991	    let mut accumulator = ExactAccumulator::new();
 992	    for &(c, v) in terms {
 993	        if accumulator.add_product(c, v).is_err() {
 994	            // Not reached for finite binary64 pairs (their products lie in the
 995	            // accumulator's range); the p-rounded state is not substituted.
 996	            return Binary64Outcome::Overflow {
 997	                negative: (c < 0.0) != (v < 0.0),
 998	            };
 999	        }
1000	    }
1001	    let negative = accumulator.signum() < 0;
1002	    match accumulator.round() {
1003	        Ok(x) if x == 0.0 => {
1004	            if accumulator.signum() == 0 {
1005	                Binary64Outcome::Normal(0.0)
1006	            } else {
1007	                Binary64Outcome::Underflow { negative }
1008	            }
1009	        }
1010	        // The rounded value is exact in `Wide`: K3's conversion only labels it
1011	        // (normal, or subnormal with its relative precision).
1012	        Ok(x) => Wide::<4>::from_f64(x)
1013	            .map(|w| w.to_binary64())
1014	            .unwrap_or(Binary64Outcome::Overflow { negative }),
1015	        Err(_) => Binary64Outcome::Overflow { negative },
1016	    }
1017	}
