1413	/// The residual gate of the free rows, exactly: per row, whether
1414	/// |r|·(2^p − m) ≤ 64·m·d, the approximate ratio, and r rounded once to p.
1415	#[allow(clippy::too_many_arguments)]
1416	fn residual_rows<const L: usize, const R: usize>(
1417	    ctx: &mut WideContext<L>,
1418	    ctx_q: &mut WideContext<R>,
1419	    ctx64: &mut WideContext<4>,
1420	    ctx16: &mut WideContext<16>,
1421	    sum: &mut ExactWideSum,
1422	    p: u32,
1423	    structure: &Structure,
1424	    k_q: &[Wide<R>],
1425	    ledger: &RetainedLedger,
1426	    free: &[usize],
1427	    u: &[Wide<L>],
1428	    tracker: &mut BoundedExtremeTracker,
1429	) -> Result<Vec<(bool, f64, Wide<L>)>, AttemptStop>
1430	where
1431	    Wide<L>: SupportedWidth,
1432	    Wide<R>: SupportedWidth,
1433	{
1434	    let mut rows = Vec::with_capacity(free.len());
1435	    for &i in free {
1436	        // r_i = f_i − Σ_j K^q_ij·u_j (exact); d_i = |f_i| + Σ_j |K^q_ij·u_j|.
1437	        let mut r = ExactWideSum::new();
1438	        let mut d = ExactWideSum::new();
1439	        ledger.add_to(i, &mut r, false)?;
1440	        if let Some(net) = ledger.net(i) {
1441	            if !net.is_zero() {
1442	                d.add_integer(false, &net.magnitude, net.exponent)?;
1443	            }
1444	        }
1445	        let mut count = 0u64;
1446	        for index in structure.pattern.row_range(i) {
1447	            let j = structure.pattern.column(index);
1448	            let kij = &k_q[index];
1449	            let uj = u[j].widen::<R>();
1450	            if kij.is_zero() || uj.is_zero() {
1451	                continue;
1452	            }
1453	            count += 1;
1454	            r.add_product(ctx_q, kij, &uj, true)?;
1455	            let negative = kij.is_sign_negative() != uj.is_sign_negative();
1456	            d.add_product(ctx_q, kij, &uj, negative)?;
1457	        }
1458	        let m = 2 * count + 2;
1459	        let mut absolute = r.clone();
1460	        absolute.make_absolute();
1461	        // num = |r|·(2^p − m), den = 64·m·d.
1462	        let mut num = ExactWideSum::new();
1463	        num.add_scaled(&absolute, false, 1, i64::from(p))?;
1464	        num.add_scaled(&absolute, true, m, 0)?;
1465	        let mut den = ExactWideSum::new();
1466	        den.add_scaled(&d, false, 64 * m, 0)?;
1467	        // Gate: den − num ≥ 0.
1468	        sum.clear();
1469	        sum.add_scaled(&den, false, 1, 0)?;
1470	        sum.add_scaled(&num, true, 1, 0)?;
1471	        let passes = sum.signum() >= 0;
1472	        let ratio = approximate_ratio(ctx64, &num, &den)?;
1473	        let rounded = r.round(ctx)?;
1474	        tracker.offer(ctx64, ctx16, num, den)?;
1475	        rows.push((passes, ratio, rounded));
1476	    }
1477	    Ok(rows)
1478	}
