1480	/// num/den against another exact ratio (dens positive), decided exactly.
1481	fn cmp_ratio(
1482	    a: &(ExactWideSum, ExactWideSum),
1483	    b: &(ExactWideSum, ExactWideSum),
1484	) -> Result<CmpOrdering, AttemptStop> {
1485	    let mut t = ExactWideSum::new();
1486	    let mut db = b.1.clone();
1487	    t.add_product_of(&a.0, &mut db, false)?;
1488	    let mut da = a.1.clone();
1489	    t.add_product_of(&b.0, &mut da, true)?;
1490	    Ok(t.signum().cmp(&0))
1491	}
1492	
1493	/// An exact ratio num/den (den > 0).
1494	pub(crate) type GateRatio = (ExactWideSum, ExactWideSum);
1495	
1496	/// The gate's bounded row test (R7 §4.1.4 step 3), exactly: with
1497	/// num = |r|·(2^p − m) and den = 64·m·d^b, whether num ≤ den, and the pair.
1498	pub(crate) fn bounded_row(
1499	    r: ExactWideSum,
1500	    d: &ExactWideSum,
1501	    m: u64,
1502	    p: u32,
1503	    sum: &mut ExactWideSum,
1504	) -> Result<(bool, GateRatio), AttemptStop> {
1505	    let mut absolute = r;
1506	    absolute.make_absolute();
1507	    let mut num = ExactWideSum::new();
1508	    num.add_scaled(&absolute, false, 1, i64::from(p))?;
1509	    num.add_scaled(&absolute, true, m, 0)?;
1510	    let mut den = ExactWideSum::new();
1511	    den.add_scaled(d, false, 64 * m, 0)?;
1512	    sum.clear();
1513	    sum.add_scaled(&den, false, 1, 0)?;
1514	    sum.add_scaled(&num, true, 1, 0)?;
1515	    Ok((sum.signum() >= 0, (num, den)))
1516	}
