1518	/// The best evaluated state (ROOT's A3-0 ruling Q6): per state, None when it
1519	/// is not eligible, Some(None) when every row's residual is zero, or
1520	/// Some(Some(worst bounded ratio)). The smallest worst ratio wins, compared
1521	/// exactly, and the earliest state on a tie.
1522	pub(crate) fn best_gate_state(
1523	    worst: &[Option<Option<GateRatio>>],
1524	) -> Result<Option<usize>, AttemptStop> {
1525	    let mut best: Option<(usize, &Option<GateRatio>)> = None;
1526	    for (k, state) in worst.iter().enumerate() {
1527	        let Some(w) = state else { continue };
1528	        let replace = match &best {
1529	            None => true,
1530	            Some((_, b)) => match (w, b) {
1531	                (None, None) | (Some(_), None) => false,
1532	                (None, Some(_)) => true,
1533	                (Some(w), Some(b)) => cmp_ratio(w, b)? == CmpOrdering::Less,
1534	            },
1535	        };
1536	        if replace {
1537	            best = Some((k, w));
1538	        }
1539	    }
1540	    Ok(best.map(|b| b.0))
1541	}
