1543	/// The gate's fallback (D1 revision 5a.3, R7 §4.1.4 step 3; ROOT's A3-0
1544	/// rulings Q6 and Q17): Ā^q formed once at q from the coefficients kept at q;
1545	/// per evaluated state, the exact rows with the bounded denominator
1546	/// d_i^b = |f_i| + Σ_j Ā^q_ij·|u_j| and m_i as the coalesced test's. A state
1547	/// with a nonzero residual on a row with d^b = 0 is not eligible. The best
1548	/// state (`best_gate_state`) passes when every row passes
1549	/// |r_i|(2^p − m_i) ≤ 64·m_i·d_i^b (`bounded_row`).
1550	/// Returns (its index, fl↑ of its worst bounded ratio), or None.
1551	#[allow(clippy::too_many_arguments)]
1552	fn bounded_fallback<const L: usize, const R: usize>(
1553	    ctx_q: &mut WideContext<R>,
1554	    ctx64: &mut WideContext<4>,
1555	    ctx16: &mut WideContext<16>,
1556	    sum: &mut ExactWideSum,
1557	    p: u32,
1558	    shared: &Shared<L, R>,
1559	    prep: &CasePrep,
1560	    group: &GroupPrep,
1561	    u_base: &[Wide<L>],
1562	    evaluated: &[Vec<Wide<L>>],
1563	    guard: &StageGuard,
1564	) -> Result<Option<(usize, f64)>, AttemptStop>
1565	where
1566	    Wide<L>: SupportedWidth,
1567	    Wide<R>: SupportedWidth,
1568	{
1569	    let structure = &group.structure;
1570	    let free = &group.ordering.free;
1571	    let abar_q = assemble_bounded(
1572	        ctx_q,
1573	        sum,
1574	        guard,
1575	        &prep.source,
1576	        structure,
1577	        &shared.bounded_q,
1578	        &shared.directional_q,
1579	    )?;
1580	    let mut worsts: Vec<Option<Option<GateRatio>>> = Vec::with_capacity(evaluated.len());
1581	    let mut states: Vec<Option<(bool, BoundedExtremeTracker)>> =
1582	        Vec::with_capacity(evaluated.len());
1583	    for u_free in evaluated {
1584	        let mut u = u_base.to_vec();
1585	        for (a, &g) in free.iter().enumerate() {
1586	            u[g] = u_free[a];
1587	        }
1588	        let mut eligible = true;
1589	        let mut all_pass = true;
1590	        let mut tracker = BoundedExtremeTracker::new(Direction::Up);
1591	        let mut rows: Vec<(ExactWideSum, ExactWideSum, f64)> = Vec::new();
1592	        for &i in free {
1593	            let mut r = ExactWideSum::new();
1594	            let mut d = ExactWideSum::new();
1595	            prep.ledger.add_to(i, &mut r, false)?;
1596	            if let Some(net) = prep.ledger.net(i) {
1597	                if !net.is_zero() {
1598	                    d.add_integer(false, &net.magnitude, net.exponent)?;
1599	                }
1600	            }
1601	            let mut count = 0u64;
1602	            for index in structure.pattern.row_range(i) {
1603	                let j = structure.pattern.column(index);
1604	                let uj = u[j].widen::<R>();
1605	                if uj.is_zero() {
1606	                    continue;
1607	                }
1608	                let kij = &shared.k_q[index];
1609	                if !kij.is_zero() {
1610	                    count += 1;
1611	                    r.add_product(ctx_q, kij, &uj, true)?;
1612	                }
1613	                let aij = &abar_q[index];
1614	                if !aij.is_zero() {
1615	                    d.add_product(ctx_q, aij, &uj.abs(), false)?;
1616	                }
1617	            }
1618	            let m = 2 * count + 2;
1619	            let (passes, (mut num, mut den)) = bounded_row(r, &d, m, p, sum)?;
1620	            all_pass &= passes;
1621	            if num.is_zero() {
1622	                continue;
1623	            }
1624	            if den.is_zero() {
1625	                eligible = false;
1626	                break;
1627	            }
1628	            let approx = approximate_ratio(ctx64, &num, &den)?;
1629	            tracker.offer(ctx64, ctx16, num.clone(), den.clone())?;
1630	            rows.push((num, den, approx));
1631	        }
1632	        if !eligible {
1633	            worsts.push(None);
1634	            states.push(None);
1635	            continue;
1636	        }
1637	        // The exact worst row, among those whose 64-bit approximation lies
1638	        // within a relative 2^-40 of the largest (the approximations are within
1639	        // a few 2^-64 of the exact ratios).
1640	        let top = rows.iter().map(|r| r.2).fold(0.0f64, f64::max);
1641	        let floor = top - top * f64::from_bits(0x3D70_0000_0000_0000); // 2^-40
1642	        let mut worst: Option<GateRatio> = None;
1643	        for (num, den, approx) in rows {
1644	            if approx < floor {
1645	                continue;
1646	            }
1647	            let candidate = (num, den);
1648	            let greater = match &worst {
1649	                None => true,
1650	                Some(w) => cmp_ratio(&candidate, w)? == CmpOrdering::Greater,
1651	            };
1652	            if greater {
1653	                worst = Some(candidate);
1654	            }
1655	        }
1656	        worsts.push(Some(worst));
1657	        states.push(Some((all_pass, tracker)));
1658	    }
1659	    let Some(k) = best_gate_state(&worsts)? else {
1660	        return Ok(None);
1661	    };
1662	    match states.swap_remove(k) {
1663	        Some((true, tracker)) => Ok(Some((k, tracker.finish(ctx16)?.unwrap_or(0.0)))),
1664	        _ => Ok(None),
1665	    }
1666	}
