1668	#[allow(clippy::too_many_arguments)]
1669	fn solve_case_at<const L: usize, const R: usize>(
1670	    shared: &Shared<L, R>,
1671	    prep: &CasePrep,
1672	    group: &GroupPrep,
1673	    guard: StageGuard,
1674	) -> Spent<Solved<L>>
1675	where
1676	    Wide<L>: SupportedWidth,
1677	    Wide<R>: SupportedWidth,
1678	{
1679	    let p = shared.p;
1680	    let mut ctx = WideContext::<L>::new(p).expect("supported precision");
1681	    let mut ctx_q = WideContext::<R>::new(shared.q).expect("supported precision");
1682	    let mut ctx16 = WideContext::<16>::new(1024).expect("supported precision");
1683	    let mut ctx64 = WideContext::<4>::new(64).expect("supported precision");
1684	    let mut sum = ExactWideSum::new();
1685	    let mut stages = StageWork::default();
1686	    let source = &prep.source;
1687	    let free = &group.ordering.free;
1688	    // T3 KF3: the stage in progress, for a stopped solve's unstaged work.
1689	    let mut current = Stage::Rhs;
1690	    let mut run = || -> Result<Solved<L>, AttemptStop> {
1691	        let total = |ctx: &WideContext<L>,
1692	                     ctx_q: &WideContext<R>,
1693	                     ctx16: &WideContext<16>,
1694	                     ctx64: &WideContext<4>,
1695	                     sum: &ExactWideSum| {
1696	            lme(ctx) + lme(ctx_q) + lme(ctx16) + lme(ctx64) + sum.work().limb_multiply_equivalents()
1697	        };
1698	        let t0 = total(&ctx, &ctx_q, &ctx16, &ctx64, &sum);
1699	        // The prescribed values at p (exact for a case's binary64 values; a
1700	        // combination's exact sum, rounded once).
1701	        let mut u = vec![Wide::<L>::ZERO; source.dof_count()];
1702	        prep.prescribed_at(&mut ctx, &mut sum, &mut u)?;
1703	        let rhs = reduced_rhs(
1704	            &mut ctx,
1705	            &mut sum,
1706	            source,
1707	            &group.structure,
1708	            &shared.k,
1709	            &prep.ledger,
1710	            free,
1711	            &u,
