545	impl Structure {
546	    /// `SparsePattern::from_positions` of the member 12×12 blocks, the spring
547	    /// diagonals and the directional springs' 3×3 node blocks.
548	    pub(crate) fn new(source: &PrimitiveSource) -> Result<Self, AttemptStop> {
549	        let n = source.dof_count();
550	        let mut positions: Vec<(usize, usize)> = Vec::new();
551	        let member_dofs = |m: &StraightMember| {
552	            let mut out = [0usize; 12];
553	            for k in 0..6 {
554	                out[k] = m.node_i as usize * DOF_PER_NODE + k;
555	                out[6 + k] = m.node_j as usize * DOF_PER_NODE + k;
556	            }
557	            out
558	        };
559	        for m in source.members() {
560	            let dofs = member_dofs(m);
561	            for &r in &dofs {
562	                for &c in &dofs {
563	                    if r <= c {
564	                        positions.push((r, c));
565	                    }
566	                }
567	            }
568	        }
569	        for s in source.springs() {
570	            let d = s.dof.global();
571	            positions.push((d, d));
572	        }
573	        for s in source.directional_springs() {
574	            let base = s.node as usize * DOF_PER_NODE + s.kind.offset();
575	            for a in 0..3 {
576	                for b in a..3 {
577	                    positions.push((base + a, base + b));
578	                }
579	            }
580	        }
581	        let pattern = SparsePattern::from_positions(n, positions.iter().copied())
582	            .map_err(|_| AttemptStop::Structure)?;
583	        let entries = pattern.entry_count();
584	        let mut tagged: Vec<(usize, Contribution)> = Vec::new();
585	        let find = |r: usize, c: usize| pattern.find(r, c).ok_or(AttemptStop::Structure);
586	        for (index, m) in source.members().iter().enumerate() {
587	            let dofs = member_dofs(m);
588	            for a in 0..12 {
589	                for b in 0..12 {
590	                    if dofs[a] <= dofs[b] {
591	                        tagged.push((
592	                            find(dofs[a], dofs[b])?,
593	                            Contribution::Member {
594	                                member: index as u32,
595	                                a: a as u8,
596	                                b: b as u8,
597	                            },
598	                        ));
599	                    }
600	                }
601	            }
602	        }
603	        for (index, s) in source.springs().iter().enumerate() {
604	            let d = s.dof.global();
605	            tagged.push((
606	                find(d, d)?,
607	                Contribution::Spring {
608	                    spring: index as u32,
609	                },
610	            ));
611	        }
612	        for (index, s) in source.directional_springs().iter().enumerate() {
613	            let base = s.node as usize * DOF_PER_NODE + s.kind.offset();
614	            for a in 0..3 {
615	                for b in a..3 {
616	                    tagged.push((
617	                        find(base + a, base + b)?,
618	                        Contribution::Directional {
619	                            spring: index as u32,
620	                            a: a as u8,
621	                            b: b as u8,
622	                        },
623	                    ));
624	                }
625	            }
626	        }
627	        // Counting sort by entry (stable: member order, then springs).
628	        let mut counts = vec![0usize; entries + 1];
629	        for (entry, _) in &tagged {
630	            counts[entry + 1] += 1;
631	        }
632	        for k in 0..entries {
633	            counts[k + 1] += counts[k];
634	        }
635	        let starts = counts.clone();
636	        let mut next = counts;
637	        let mut items = vec![Contribution::Spring { spring: 0 }; tagged.len()];
638	        for (entry, item) in tagged {
639	            items[next[entry]] = item;
640	            next[entry] += 1;
641	        }
642	        Ok(Self {
643	            pattern,
644	            starts,
645	            items,
646	        })
647	    }
648	
649	    /// Stored pattern entries (both triangles).
650	    pub(crate) fn entry_count(&self) -> usize {
651	        self.pattern.entry_count()
652	    }
653	
654	    /// The contributions of an upper-triangle (row ≤ col) entry: member
655	    /// entries (a, b) with row = dofs[a] and col = dofs[b], springs, and
656	    /// directional-block entries (a, b). A lower entry reads its transpose's.
657	    pub(crate) fn contributions(&self, upper: usize) -> &[Contribution] {
658	        &self.items[self.starts[upper]..self.starts[upper + 1]]
659	    }
660	
661	    /// (row, col, entry index) of every stored entry, rows ascending.
662	    pub(crate) fn entries(&self) -> impl Iterator<Item = (usize, usize, usize)> + '_ {
663	        (0..self.pattern.dimension()).flat_map(move |row| {
664	            self.pattern
665	                .row_range(row)
666	                .map(move |index| (row, self.pattern.column(index), index))
667	        })
668	    }
669	}
