671	/// The assembled K at the context's precision: one value per pattern entry.
672	pub(crate) fn assemble<const L: usize>(
673	    ctx: &mut WideContext<L>,
674	    sum: &mut ExactWideSum,
675	    guard: &StageGuard,
676	    source: &PrimitiveSource,
677	    structure: &Structure,
678	    members: &[MemberOperators<L>],
679	    directional: &[DirectionalBlock<L>],
680	) -> Result<Vec<Wide<L>>, AttemptStop>
681	where
682	    Wide<L>: SupportedWidth,
683	{
684	    let mut values = vec![Wide::<L>::ZERO; structure.entry_count()];
685	    let mut done = vec![false; structure.entry_count()];
686	    for (row, col, index) in structure.entries() {
687	        if row > col {
688	            continue;
689	        }
690	        sum.clear();
691	        for item in &structure.items[structure.starts[index]..structure.starts[index + 1]] {
692	            match *item {
693	                Contribution::Member { member, a, b } => {
694	                    sum.add_wide(members[member as usize].ke(a as usize, b as usize), false)?
695	                }
696	                Contribution::Spring { spring } => {
697	                    sum.add_binary64(source.springs()[spring as usize].stiffness, false)?
698	                }
699	                Contribution::Directional { spring, a, b } => sum.add_wide(
700	                    &directional[spring as usize].k[a as usize][b as usize],
701	                    false,
702	                )?,
703	            }
704	        }
705	        values[index] = sum.round(ctx)?;
706	        // V-K seeded fault VK-F03 (§7.3-4): the smallest contribution to a
707	        // diagonal entry dropped (R1's NC-LOST-SOFT).
708	        #[cfg(any(test, feature = "mutation-controls"))]
709	        if row == col && super::seeded::active(super::seeded::Fault::F03) {
710	            let items = &structure.items[structure.starts[index]..structure.starts[index + 1]];
711	            if items.len() > 1 {
712	                let mut terms: Vec<Wide<L>> = Vec::with_capacity(items.len());
713	                for item in items {
714	                    terms.push(match *item {
715	                        Contribution::Member { member, a, b } => {
716	                            *members[member as usize].ke(a as usize, b as usize)
717	                        }
718	                        Contribution::Spring { spring } => {
719	                            lift::<L>(source.springs()[spring as usize].stiffness)?
720	                        }
721	                        Contribution::Directional { spring, a, b } => {
722	                            directional[spring as usize].k[a as usize][b as usize]
723	                        }
724	                    });
725	                }
726	                let smallest = (0..terms.len())
727	                    .min_by(|&x, &y| terms[x].abs().cmp_value(&terms[y].abs()))
728	                    .unwrap();
729	                sum.clear();
730	                for (t, term) in terms.iter().enumerate() {
731	                    if t != smallest {
732	                        sum.add_wide(term, false)?;
733	                    }
734	                }
735	                values[index] = sum.round(ctx)?;
736	            }
737	        }
738	        // V-K seeded fault VK-F01 (§7.3-1): the entry promoted from its
739	        // binary64 rounding.
740	        #[cfg(any(test, feature = "mutation-controls"))]
741	        if super::seeded::active(super::seeded::Fault::F01) {
742	            let rounded = values[index].to_binary64().value().unwrap_or(0.0);
743	            values[index] = lift::<L>(rounded)?;
744	        }
745	        done[index] = true;
746	        if row == col {
747	            guard.check(ctx, sum)?;
748	        }
749	    }
750	    for (row, col, index) in structure.entries() {
751	        if row > col {
752	            let mirror = structure.pattern.transpose(index);
753	            debug_assert!(done[mirror]);
754	            values[index] = values[mirror];
755	        }
756	    }
757	    Ok(values)
758	}
