760	/// Ā at the context's precision (module documentation): one value per pattern
761	/// entry, both triangles formed separately (the lower triangle reads the
762	/// element blocks' (b, a) entries), each one exact sum rounded once.
763	pub(crate) fn assemble_bounded<const L: usize>(
764	    ctx: &mut WideContext<L>,
765	    sum: &mut ExactWideSum,
766	    guard: &StageGuard,
767	    source: &PrimitiveSource,
768	    structure: &Structure,
769	    members: &[BoundedCoefficients<L>],
770	    directional: &[DirectionalBlock<L>],
771	) -> Result<Vec<Wide<L>>, AttemptStop>
772	where
773	    Wide<L>: SupportedWidth,
774	{
775	    let mut blocks = Vec::with_capacity(members.len());
776	    for m in members {
777	        blocks.push(bounded_block(ctx, sum, m)?);
778	        guard.check(ctx, sum)?;
779	    }
780	    let mut values = vec![Wide::<L>::ZERO; structure.entry_count()];
781	    for (row, col, index) in structure.entries() {
782	        let (upper, mirrored) = if row <= col {
783	            (index, false)
784	        } else {
785	            (structure.pattern.transpose(index), true)
786	        };
787	        sum.clear();
788	        for item in &structure.items[structure.starts[upper]..structure.starts[upper + 1]] {
789	            match *item {
790	                Contribution::Member { member, a, b } => {
791	                    let (a, b) = if mirrored { (b, a) } else { (a, b) };
792	                    sum.add_wide(&blocks[member as usize][a as usize][b as usize], false)?
793	                }
794	                Contribution::Spring { spring } => {
795	                    sum.add_binary64(source.springs()[spring as usize].stiffness.abs(), false)?
796	                }
797	                Contribution::Directional { spring, a, b } => {
798	                    let (a, b) = if mirrored { (b, a) } else { (a, b) };
799	                    sum.add_wide(
800	                        &directional[spring as usize].k[a as usize][b as usize].abs(),
801	                        false,
802	                    )?
803	                }
804	            }
805	        }
806	        values[index] = sum.round(ctx)?;
807	        if row == col {
808	            guard.check(ctx, sum)?;
809	        }
810	    }
811	    Ok(values)
812	}
