320	/// Otherwise, whether y is parallel to it, decided exactly: (x_j − x_i) × y = 0.
321	fn chord_checks(xi: [f64; 3], xj: [f64; 3], y: [f64; 3]) -> (bool, bool) {
322	    let mut d: Vec<ExactWideSum> = Vec::with_capacity(3);
323	    let mut zero = true;
324	    for k in 0..3 {
325	        let mut s = ExactWideSum::new();
326	        s.add_binary64(xj[k], false).expect("finite");
327	        s.add_binary64(xi[k], true).expect("finite");
328	        zero &= s.is_zero();
329	        d.push(s);
330	    }
331	    if zero {
332	        return (true, false);
333	    }
334	    let mut parallel = true;
335	    for (a, b) in [(1usize, 2usize), (2, 0), (0, 1)] {
336	        // d_a·y_b − d_b·y_a
337	        let mut c = ExactWideSum::new();
338	        if y[b] != 0.0 {
339	            let (neg, sig, lsb) = binary64_parts(y[b]);
340	            c.add_scaled(&d[a], neg, sig, lsb).expect("in span");
341	        }
342	        if y[a] != 0.0 {
343	            let (neg, sig, lsb) = binary64_parts(y[a]);
344	            c.add_scaled(&d[b], !neg, sig, lsb).expect("in span");
345	        }
346	        parallel &= c.is_zero();
347	    }
348	    (false, parallel)
349	}
