693	    fn encode_stiffness_part(&self, out: &mut Vec<u8>, constraint_values: bool) {
694	        put_u32(out, self.nodes.len() as u32);
695	        for p in &self.nodes {
696	            for &c in p {
697	                put_f64(out, c);
698	            }
699	        }
700	        put_u32(out, self.members.len() as u32);
701	        for m in &self.members {
702	            put_u32(out, m.id);
703	            put_u32(out, m.node_i);
704	            put_u32(out, m.node_j);
705	            for v in [
706	                m.elastic_modulus,
707	                m.shear_modulus,
708	                m.area,
709	                m.second_moment_y,
710	                m.second_moment_z,
711	                m.torsion_constant,
712	            ] {
713	                put_f64(out, v);
714	            }
715	            for &c in &m.y_reference {
716	                put_f64(out, c);
717	            }
718	        }
719	        put_u32(out, self.springs.len() as u32);
720	        for s in &self.springs {
721	            put_u32(out, s.id);
722	            put_dof(out, s.dof);
723	            put_f64(out, s.stiffness);
724	        }
725	        put_u32(out, self.directional_springs.len() as u32);
726	        for s in &self.directional_springs {
727	            put_u32(out, s.id);
728	            put_u32(out, s.node);
729	            out.push(match s.kind {
730	                SpringKind::Translation => 0,
731	                SpringKind::Rotation => 1,
732	            });
733	            for &c in &s.direction {
734	                put_f64(out, c);
735	            }
736	            put_f64(out, s.stiffness);
737	        }
738	        put_u32(out, self.constraints.len() as u32);
739	        for c in &self.constraints {
740	            put_dof(out, c.dof);
741	            if constraint_values {
742	                put_f64(out, c.value);
743	            }
744	        }
745	    }

