130	pub(crate) fn geometry_first(
131	    source: &PrimitiveSource,
132	) -> Result<Vec<BodyGeometry>, GeometryRefusal> {
133	    // V-K seeded fault VK-F07 (§7.3-7): the geometric mechanism check disabled.
134	    #[cfg(any(test, feature = "mutation-controls"))]
135	    if super::seeded::active(super::seeded::Fault::F07) {
136	        return Ok(vec![
137	            BodyGeometry::NumericallyUnresolved;
138	            source.body_count() as usize
139	        ]);
140	    }
141	    let mut out = Vec::with_capacity(source.body_count() as usize);
142	    for body in 0..source.body_count() {
143	        let nodes = source.body_nodes(body);
144	        let mut local_of = std::collections::BTreeMap::new();
145	        for (local, &node) in nodes.iter().enumerate() {
146	            local_of.insert(node, local);
147	        }
148	        let coordinates: Vec<[f64; 3]> =
149	            nodes.iter().map(|&n| source.nodes()[n as usize]).collect();
150	        let mut grounds: Vec<usize> = Vec::new();
151	        let mut not_spanning: Vec<(u32, SpringKind)> = Vec::new();
152	        for &node in &nodes {
153	            let local = local_of[&node];
154	            let base = node as usize * DOF_PER_NODE;
155	            for component in 0..DOF_PER_NODE {
156	                if source.constraint(base + component).is_some() {
157	                    grounds.push(local * DOF_PER_NODE + component);
158	                }
159	            }
160	            for s in source.springs() {
161	                if s.dof.node == node {
162	                    grounds.push(local * DOF_PER_NODE + s.dof.component.index());
163	                }
164	            }
165	            for kind in [SpringKind::Translation, SpringKind::Rotation] {
166	                let directional: Vec<[f64; 3]> = source
167	                    .directional_springs()
168	                    .iter()
169	                    .filter(|s| s.node == node && s.kind == kind)
170	                    .map(|s| s.direction)
171	                    .collect();
172	                if directional.is_empty() {
173	                    continue;
174	                }
175	                let mut directions = directional;
176	                for component in kind.offset()..kind.offset() + 3 {
177	                    let rigid = source.constraint(base + component).is_some();
178	                    let sprung = source
179	                        .springs()
180	                        .iter()
181	                        .any(|s| s.dof.node == node && s.dof.component.index() == component);
182	                    if rigid || sprung {
183	                        directions.push(axis(component));
184	                    }
185	                }
186	                if spans_space(&directions) {
187	                    for component in kind.offset()..kind.offset() + 3 {
188	                        grounds.push(local * DOF_PER_NODE + component);
189	                    }
190	                } else {
191	                    not_spanning.push((node, kind));
192	                }
193	            }
194	        }
195	        if !not_spanning.is_empty() {
196	            out.push(BodyGeometry::NotAssessed(not_spanning));
197	            continue;
198	        }
199	        grounds.sort_unstable();
200	        grounds.dedup();
201	        match assess_rigid_body(
202	            &coordinates,
203	            &grounds,
204	            ObjectiveFamily::WeldedUnreleasedElasticFrames,
205	        ) {
206	            Ok(assessment) => match assessment.status {
207	                RigidBodyStatus::MechanismWitnessed => {
208	                    return Err(GeometryRefusal::MechanismWitnessed {
209	                        body,
210	                        rigid_parameters: assessment.rigid_parameters.unwrap_or([0.0; 6]),
211	                    })
212	                }
213	                RigidBodyStatus::Restrained => out.push(BodyGeometry::Restrained),
214	                RigidBodyStatus::NumericallyUnresolved | RigidBodyStatus::UnqualifiedFamily => {
215	                    out.push(BodyGeometry::NumericallyUnresolved)
216	                }
217	            },
218	            Err(error) => return Err(GeometryRefusal::Unavailable { body, error }),
219	        }
220	    }
221	    Ok(out)
222	}
