226	fn bfs_reachable(seed: usize, neighbors: &[Vec<usize>]) -> Vec<usize> {
227	    let mut marked = vec![false; neighbors.len()];
228	    marked[seed] = true;
229	    let mut reachable = vec![seed];
230	    let mut queue = VecDeque::new();
231	    queue.push_back(seed);
232	    while let Some(node) = queue.pop_front() {
233	        for &next in &neighbors[node] {
234	            if !marked[next] {
235	                marked[next] = true;
236	                reachable.push(next);
237	                queue.push_back(next);
238	            }
239	        }
240	    }
241	    reachable
242	}
243	
244	fn bfs_eccentricity(start: usize, neighbors: &[Vec<usize>]) -> (usize, Vec<usize>) {
245	    let mut marked = vec![false; neighbors.len()];
246	    marked[start] = true;
247	    let mut level = vec![start];
248	    let mut depth = 0;
249	    loop {
250	        let mut next_level = Vec::new();
251	        for &node in &level {
252	            for &next in &neighbors[node] {
253	                if !marked[next] {
254	                    marked[next] = true;
255	                    next_level.push(next);
256	                }
257	            }
258	        }
259	        if next_level.is_empty() {
260	            return (depth, level);
261	        }
262	        depth += 1;
263	        level = next_level;
264	    }
265	}
