274	fn pseudo_peripheral_start(seed: usize, neighbors: &[Vec<usize>], degrees: &[usize]) -> usize {
275	    let component = bfs_reachable(seed, neighbors);
276	    let mut candidate = min_by_degree_then_index(&component, degrees).unwrap_or(seed);
277	    let (mut candidate_eccentricity, mut last_level) = bfs_eccentricity(candidate, neighbors);
278	    loop {
279	        let next = match min_by_degree_then_index(&last_level, degrees) {
280	            Some(node) => node,
281	            None => break,
282	        };
283	        let (next_eccentricity, next_last_level) = bfs_eccentricity(next, neighbors);
284	        if next_eccentricity > candidate_eccentricity {
285	            candidate = next;
286	            candidate_eccentricity = next_eccentricity;
287	            last_level = next_last_level;
288	        } else {
289	            break;
290	        }
291	    }
292	    candidate
293	}
