692	    /// `condition`, with an optional read-only observer that sees each of the
693	    /// screen's solves y = K̃⁻¹x (R7 §4.1.6.3 item 7c's est_c). The observer
694	    /// changes nothing the screen computes.
695	    pub(crate) fn condition_observed(
696	        &self,
697	        ctx: &mut WideContext<L>,
698	        sum: &mut ExactWideSum,
699	        structure: &Structure,
700	        k: &[Wide<L>],
701	        ordering: &Ordering,
702	        mut observer: Option<&mut BlockRatios<L>>,
703	    ) -> Result<Wide<L>, AttemptStop> {
704	        let p = ctx.precision();
705	        let n = ordering.free.len();
706	        let one = Wide::<L>::ONE;
707	        if n == 0 {
708	            return Ok(one);
709	        }
710	        let lift_count =
711	            |x: usize| -> Result<Wide<L>, AttemptStop> { Ok(Wide::<L>::from_f64(x as f64)?) };
712	        // ‖K̃‖₁: the largest column sum (exact, rounded once).
713	        let mut norm = Wide::<L>::ZERO;
714	        for (a, &g) in ordering.free.iter().enumerate() {
715	            sum.clear();
716	            for index in structure.pattern.row_range(g) {
717	                let b = ordering.position[structure.pattern.column(index)];
718	                if b != usize::MAX {
719	                    sum.add_wide_scaled(&k[index].abs(), false, 1, self.scale[a] + self.scale[b])?;
720	                }
721	            }
722	            let column = sum.round(ctx)?;
723	            if column.cmp_value(&norm) == CmpOrdering::Greater {
724	                norm = column;
725	            }
726	        }
727	        let abs_sum = |ctx: &mut WideContext<L>,
728	                       sum: &mut ExactWideSum,
729	                       v: &[Wide<L>]|
730	         -> Result<Wide<L>, AttemptStop> {
731	            sum.clear();
732	            for x in v {
733	                sum.add_wide(&x.abs(), false)?;
734	            }
735	            Ok(sum.round(ctx)?)
736	        };
737	        let inverse_n = ctx.div(&one, &lift_count(n)?)?;
738	        let mut x = vec![inverse_n; n];
739	        let mut estimate = Wide::<L>::ZERO;
740	        let mut previous = n;
741	        for _ in 0..5 {
742	            let y = self.solve_scaled(ctx, &x)?;
743	            if let Some(o) = observer.as_deref_mut() {
744	                o.offer(ctx, sum, &x, &y)?;
745	            }
746	            let current = abs_sum(ctx, sum, &y)?;
747	            if current.cmp_value(&estimate) != CmpOrdering::Greater && !estimate.is_zero() {
748	                break;
749	            }
750	            estimate = current;
751	            let signs: Vec<Wide<L>> = y
752	                .iter()
753	                .map(|v| {
754	                    if v.is_zero() || !v.is_sign_negative() {
755	                        one
756	                    } else {
757	                        one.neg()
758	                    }
759	                })
760	                .collect();
761	            let z = self.solve_scaled(ctx, &signs)?;
762	            if let Some(o) = observer.as_deref_mut() {
763	                o.offer(ctx, sum, &signs, &z)?;
764	            }
765	            let mut j = 0;
766	            for i in 1..n {
767	                if z[i].abs().cmp_value(&z[j].abs()) != CmpOrdering::Less {
768	                    j = i;
769	                }
770	            }
771	            sum.clear();
772	            for i in 0..n {
773	                sum.add_product(ctx, &z[i], &x[i], false)?;
774	            }
775	            let dot = sum.round(ctx)?;
776	            if z[j].abs().cmp_value(&dot) != CmpOrdering::Greater || j == previous {
777	                break;
778	            }
779	            previous = j;
780	            x.iter_mut().for_each(|v| *v = Wide::<L>::ZERO);
781	            x[j] = one;
782	        }
783	        let mut alternating = Vec::with_capacity(n);
784	        for i in 0..n {
785	            let magnitude = if n == 1 {
786	                one
787	            } else {
788	                ctx.div(&lift_count(n - 1 + i)?, &lift_count(n - 1)?)?
