172	    for p in coordinates {
173	        let r = [p[0] - origin[0], p[1] - origin[1], p[2] - origin[2]];
174	        if r.iter().any(|x| *x != 0.0) {
175	            candidates.push([0.0, 0.0, 0.0, r[0], r[1], r[2]]);
176	        }
177	    }
178	    for candidate in candidates {
179	        // Unsupported expansion range or an inexact recovered motion is numerical
180	        // uncertainty. Neither turns a nonzero original constraint action into zero.
181	        if let Ok(Some(motions)) =
182	            original_rigid_witness(coordinates, ground_dofs, length, &candidate)
183	        {
184	            result.status = RigidBodyStatus::MechanismWitnessed;
185	            result.rigid_parameters = Some(candidate);
186	            result.node_motion = Some(motions);
187	            result.maximum_constraint_action = Some(0.0);
188	            break;
189	        }
190	    }
191	    Ok(result)
192	}
