202	    let origin = coordinates[0];
203	    let mut exact_motions = Vec::new();
204	    for p in coordinates {
205	        let mut delta: [Expansion; 3] = std::array::from_fn(|_| Expansion::default());
206	        for axis in 0..3 {
207	            delta[axis].add(p[axis])?;
208	            delta[axis].add(-origin[axis])?;
209	        }
210	        let mut motion: [Expansion; 6] = std::array::from_fn(|_| Expansion::default());
211	        for axis in 0..3 {
212	            motion[axis].add_product(length, candidate[axis], 0)?;
213	            motion[axis + 3].add(candidate[axis + 3])?;
214	        }
215	        // omega cross (x-original_origin), with exact subtraction and products.
216	        for (component, positive_axis, positive_omega, negative_axis, negative_omega) in
217	            [(0, 2, 4, 1, 5), (1, 0, 5, 2, 3), (2, 1, 3, 0, 4)]
218	        {
219	            for &part in &delta[positive_axis].terms {
220	                motion[component].add_product(part, candidate[positive_omega], 0)?;
221	            }
222	            for &part in &delta[negative_axis].terms {
223	                motion[component].add_product(-part, candidate[negative_omega], 0)?;
224	            }
