226	        exact_motions.push(motion);
227	    }
228	    if ground
229	        .iter()
230	        .any(|&d| !exact_motions[d / 6][d % 6].is_zero())
231	    {
232	        return Ok(None);
233	    }
234	    // Publish node_motion only if it exactly represents this common original-coordinate
235	    // rigid motion. A rounded recovery is not silently presented as an exact witness.
236	    let mut motions = Vec::new();
237	    for exact in exact_motions {
238	        let mut motion = [0.0; 6];
239	        for j in 0..6 {
240	            let Some(value) = exact[j].exact_scalar()? else {
241	                return Ok(None);
242	            };
243	            motion[j] = value;
244	        }
245	        motions.push(motion);
246	    }
247	    Ok(Some(motions))
