319	    /// `K * u`, bit-identical to the product's dense
320	    /// `row.iter().zip(u).map(|(a, b)| a * b).sum()` on the dense view. An
321	    /// absent entry is +0.0, whose product with `u_j` is a zero signed like
322	    /// `u_j`; such zeros change a row's sum only through the sign of a zero
323	    /// result, and only as a set (one +0.0 and one -0.0 stand for all of
324	    /// them), so one of each is appended when present.
325	    pub fn multiply(&self, u: &[f64]) -> Result<Vec<f64>, StructuralError> {
326	        let n = self.dimension();
327	        if u.len() != n {
328	            return Err(StructuralError::InvalidInput("displacement vector"));
329	        }
330	        let negative_u = u.iter().filter(|x| x.is_sign_negative()).count();
331	        let mut product = Vec::with_capacity(n);
332	        for i in 0..n {
333	            let stored = self.pattern.row(i).len();
334	            let stored_negative = self
335	                .pattern
336	                .row(i)
337	                .iter()
338	                .filter(|&&j| u[j].is_sign_negative())
339	                .count();
340	            let absent_negative = negative_u - stored_negative;
341	            let absent_positive = (n - stored) - absent_negative;
342	            let zeros = [
343	                (absent_positive > 0).then_some(0.0),
344	                (absent_negative > 0).then_some(-0.0),
345	            ];
346	            product.push(
347	                self.row(i)
348	                    .map(|(j, k)| k * u[j])
349	                    .chain(zeros.into_iter().flatten())
350	                    .sum::<f64>(),
351	            );
352	        }
353	        Ok(product)
354	    }
