 30	
 31	impl LedgerNet {
 32	    fn from_accumulator(accumulator: &ExactAccumulator) -> Self {
 33	        let (negative, magnitude, exponent) = accumulator.net_parts();
 34	        let Some(low) = magnitude.iter().position(|&l| l != 0) else {
 35	            return Self {
 36	                negative: false,
 37	                magnitude: Vec::new(),
 38	                exponent: 0,
 39	            };
 40	        };
 41	        let shift = low * 64 + magnitude[low].trailing_zeros() as usize;
 42	        let top = magnitude.iter().rposition(|&l| l != 0).unwrap();
 43	        let bits = top * 64 + 64 - magnitude[top].leading_zeros() as usize - shift;
 44	        let mut out = vec![0u64; bits.div_ceil(64)];
 45	        for (k, limb) in out.iter_mut().enumerate() {
 46	            let at = shift + 64 * k;
 47	            let (word, bit) = (at / 64, at % 64);
 48	            let lo = magnitude.get(word).copied().unwrap_or(0);
 49	            let hi = magnitude.get(word + 1).copied().unwrap_or(0);
 50	            *limb = if bit == 0 {
 51	                lo
 52	            } else {
 53	                (lo >> bit) | (hi << (64 - bit))
 54	            };
 55	        }
 56	        while out.last() == Some(&0) {
 57	            out.pop();
 58	        }
 59	        Self {
 60	            negative,
 61	            magnitude: out,
 62	            exponent: exponent + shift as i64,
 63	        }
 64	    }
