257	    #[cfg(any(test, feature = "mutation-controls"))]
258	    let seeded_u: Vec<Wide<L>>;
259	    #[cfg(any(test, feature = "mutation-controls"))]
260	    let u: &[Wide<L>] = if super::seeded::active(super::seeded::Fault::F02) {
261	        let mut rounded = Vec::with_capacity(u.len());
262	        for w in u {
263	            rounded.push(lift::<L>(w.to_binary64().value().unwrap_or(0.0))?);
264	        }
265	        seeded_u = rounded;
266	        &seeded_u
267	    } else {
268	        u
269	    };
270	    let mut values: Vec<Wide<L>> = Vec::with_capacity(layout.len());
271	    // Displacements, then node magnitudes.
272	    values.extend_from_slice(u);
273	    for node in 0..source.node_count() {
274	        let base = node * DOF_PER_NODE;
275	        values.push(magnitude(ctx, sum, &u[base..base + 3])?);
276	    }
277	    // Members.
278	    let mut q_all = Vec::with_capacity(members.len());
279	    let mut end_actions: Vec<[Wide<L>; 12]> = Vec::with_capacity(members.len());
280	    for m in members {
281	        let dofs = m.dofs();
282	        // d_local = T u: block b (tr_i, rot_i, tr_j, rot_j), local axis r.
283	        let mut d = [zero; 12];
284	        for block in 0..4 {
285	            for r in 0..3 {
286	                sum.clear();
287	                for c in 0..3 {
288	                    sum.add_product(ctx, &m.axes[r][c], &u[dofs[3 * block + c]], false)?;
289	                }
290	                d[3 * block + r] = sum.round(ctx)?;
291	            }
292	        }
293	        let inv = &m.inv_length;
294	        let mut e = [zero; 6];
295	        // e0 = u_j − u_i, e1 = θx_j − θx_i (local).
296	        for (index, (plus, minus)) in [(6usize, 0usize), (9, 3)].into_iter().enumerate() {
297	            sum.clear();
298	            sum.add_wide(&d[plus], false)?;
299	            sum.add_wide(&d[minus], true)?;
300	            e[index] = sum.round(ctx)?;
301	        }
302	        // e2, e3 = θz − (v_j − v_i)/L; e4, e5 = θy + (w_j − w_i)/L.
303	        for (index, rotation, transverse, sign) in [
304	            (2usize, 5usize, 1usize, true),
305	            (3, 11, 1, true),
306	            (4, 4, 2, false),
307	            (5, 10, 2, false),
308	        ] {
309	            sum.clear();
310	            sum.add_wide(&d[rotation], false)?;
311	            // θz: + (v_i − v_j)/L; θy: − (w_i − w_j)/L.
312	            sum.add_product(ctx, inv, &d[transverse], !sign)?;
313	            sum.add_product(ctx, inv, &d[transverse + 6], sign)?;
314	            e[index] = sum.round(ctx)?;
315	        }
316	        let four_z = m.bend_z.mul_pow2(2)?;
317	        let two_z = m.bend_z.mul_pow2(1)?;
318	        let four_y = m.bend_y.mul_pow2(2)?;
319	        let two_y = m.bend_y.mul_pow2(1)?;
320	        let mut q = [zero; 6];
321	        for (index, terms) in [
322	            [(m.axial, 0usize), (zero, 0)],
323	            [(m.torsion, 1), (zero, 1)],
324	            [(four_z, 2), (two_z, 3)],
325	            [(two_z, 2), (four_z, 3)],
326	            [(four_y, 4), (two_y, 5)],
327	            [(two_y, 4), (four_y, 5)],
328	        ]
329	        .into_iter()
330	        .enumerate()
331	        {
332	            sum.clear();
333	            for (coefficient, at) in terms {
334	                sum.add_product(ctx, &coefficient, &e[at], false)?;
335	            }
336	            q[index] = sum.round(ctx)?;
337	        }
338	        // End actions B_localᵀ Q.
339	        let shear = |ctx: &mut WideContext<L>,
340	                     sum: &mut ExactWideSum,
341	                     a: &Wide<L>,
342	                     b: &Wide<L>,
343	                     negate: bool|
344	         -> Result<Wide<L>, AttemptStop> {
345	            sum.clear();
346	            sum.add_product(ctx, inv, a, negate)?;
347	            sum.add_product(ctx, inv, b, negate)?;
348	            Ok(sum.round(ctx)?)
349	        };
350	        let vy_i = shear(ctx, sum, &q[2], &q[3], false)?;
351	        let vz_i = shear(ctx, sum, &q[4], &q[5], true)?;
352	        let actions = [
353	            q[0].neg(),
354	            vy_i,
355	            vz_i,
356	            q[1].neg(),
357	            q[4],
358	            q[2],
359	            q[0],
360	            vy_i.neg(),
361	            vz_i.neg(),
362	            q[1],
363	            q[5],
364	            q[3],
365	        ];
366	        end_actions.push(actions);
367	        q_all.push(q);
368	        guard.check(ctx, sum)?;
369	    }
370	    for actions in &end_actions {
371	        values.extend_from_slice(actions);
372	    }
373	    // Stations.
374	    for s in source.stations() {
375	        let index = source.member_index(s.member).unwrap();
376	        let q = &q_all[index];
377	        let actions = &end_actions[index];
378	        let t = lift::<L>(s.fraction)?;
379	        let moment = |ctx: &mut WideContext<L>,
380	                      sum: &mut ExactWideSum,
381	                      at_j: &Wide<L>,
382	                      at_i: &Wide<L>|
383	         -> Result<Wide<L>, AttemptStop> {
384	            sum.clear();
385	            sum.add_product(ctx, &t, at_j, false)?;
386	            sum.add_product(ctx, &t, at_i, false)?;
387	            sum.add_wide(at_i, true)?;
388	            Ok(sum.round(ctx)?)
389	        };
390	        let my = moment(ctx, sum, &q[5], &q[4])?;
391	        let mz = moment(ctx, sum, &q[3], &q[2])?;
392	        values.extend_from_slice(&[actions[6], actions[7], actions[8], actions[9], my, mz]);
393	    }
394	    // Spring actions.
395	    let mut spring_action = Vec::with_capacity(source.springs().len());
396	    for s in source.springs() {
397	        sum.clear();
398	        sum.add_product(ctx, &lift::<L>(s.stiffness)?, &u[s.dof.global()], true)?;
399	        let action = sum.round(ctx)?;
400	        spring_action.push(action);
401	        values.push(action);
402	    }
403	    let mut directional_action = Vec::with_capacity(directional.len());
404	    for block in directional {
405	        let base = block.node as usize * DOF_PER_NODE + block.kind.offset();
406	        let mut components = [zero; 3];
407	        for a in 0..3 {
408	            sum.clear();
409	            for b in 0..3 {
410	                sum.add_product(ctx, &block.k[a][b], &u[base + b], true)?;
411	            }
412	            components[a] = sum.round(ctx)?;
413	        }
414	        values.extend_from_slice(&components);
415	        directional_action.push(components);
416	    }
417	    // Reactions: Σ_j K_cj·u_j − f_c, exact (the ledger enters exactly).
418	    let mut reaction = vec![None; source.dof_count()];
419	    for c in source.constraints() {
420	        let g = c.dof.global();
421	        sum.clear();
422	        for index in structure.pattern.row_range(g) {
423	            let j = structure.pattern.column(index);
424	            sum.add_product(ctx, &k[index], &u[j], false)?;
425	        }
426	        ledger.add_to(g, sum, true)?;
427	        let r = sum.round(ctx)?;
428	        // V-K seeded fault VK-S2: the reaction with the opposite sign.
429	        #[cfg(any(test, feature = "mutation-controls"))]
430	        let r = if super::seeded::active(super::seeded::Fault::S2) {
431	            r.neg()
432	        } else {
433	            r
434	        };
435	        reaction[g] = Some(r);
436	        values.push(r);
437	    }
438	    guard.check(ctx, sum)?;
439	    // Support groups: components as exact sums of the group's reactions and
440	    // spring actions (each already rounded once), then the magnitudes.
441	    for group in source.supports() {
442	        let mut components = [zero; 6];
443	        for (c, component) in components.iter_mut().enumerate() {
444	            let g = group.node as usize * DOF_PER_NODE + c;
445	            sum.clear();
446	            if group.restrained[c] {
447	                if let Some(r) = &reaction[g] {
448	                    sum.add_wide(r, false)?;
449	                }
450	            }
451	            for id in &group.springs {
452	                let k = source.springs().binary_search_by_key(id, |s| s.id).unwrap();
453	                if source.springs()[k].dof.component.index() == c {
454	                    sum.add_wide(&spring_action[k], false)?;
455	                }
456	            }
457	            for id in &group.directional_springs {
458	                let k = source
459	                    .directional_springs()
460	                    .binary_search_by_key(id, |s| s.id)
461	                    .unwrap();
462	                let s = &source.directional_springs()[k];
463	                let offset = s.kind.offset();
464	                if (offset..offset + 3).contains(&c) {
465	                    sum.add_wide(&directional_action[k][c - offset], false)?;
466	                }
467	            }
468	            *component = sum.round(ctx)?;
469	        }
470	        values.push(magnitude(ctx, sum, &components[..3])?);
471	        values.push(magnitude(ctx, sum, &components[3..])?);
472	    }
473	    debug_assert_eq!(values.len(), layout.len());
474	    let _ = SpringKind::Translation;
475	    Ok(Recovered { q: q_all, values })
476	}
