495	/// Deterministic reverse Cuthill-McKee ordering.
496	///
497	/// Returns a permutation where `order[k]` is the original index of the `k`-th
498	/// node in the new ordering. Determinism properties (documented in the crate
499	/// README): the result is a pure function of the graph structure; adjacency
500	/// lists are symmetrized, sorted, and deduplicated internally; components are
501	/// processed in order of their lowest original index; the start node of each
502	/// component is a pseudo-peripheral node found by deterministic
503	/// level-structure iteration; all ties break by ascending `(degree, original
504	/// index)`. No randomization is used anywhere.
505	pub fn reverse_cuthill_mckee(adjacency: &[Vec<usize>]) -> Result<Vec<usize>, SparseDirectError> {
506	    let node_count = adjacency.len();
507	
508	    let mut neighbors: Vec<Vec<usize>> = vec![Vec::new(); node_count];
509	    for (node, raw_list) in adjacency.iter().enumerate() {
510	        for &other in raw_list {
511	            if other >= node_count {
512	                return Err(SparseDirectError::InvalidOrdering {
513	                    detail: "adjacency index outside node count",
514	                });
515	            }
516	            if other != node {
517	                neighbors[node].push(other);
518	                neighbors[other].push(node);
519	            }
520	        }
521	    }
522	    for list in &mut neighbors {
523	        list.sort_unstable();
524	        list.dedup();
525	    }
526	
527	    let degrees: Vec<usize> = neighbors.iter().map(Vec::len).collect();
528	    for list in &mut neighbors {
529	        list.sort_by_key(|&node| (degrees[node], node));
530	    }
531	
532	    let mut visited = vec![false; node_count];
533	    let mut order = Vec::with_capacity(node_count);
534	    for seed in 0..node_count {
535	        if visited[seed] {
536	            continue;
537	        }
538	        let start = pseudo_peripheral_start(seed, &neighbors, &degrees);
539	
540	        visited[start] = true;
541	        let mut queue = VecDeque::new();
542	        queue.push_back(start);
543	        while let Some(node) = queue.pop_front() {
544	            order.push(node);
545	            for &next in &neighbors[node] {
546	                if !visited[next] {
547	                    visited[next] = true;
548	                    queue.push_back(next);
549	                }
550	            }
551	        }
552	    }
553	
554	    order.reverse();
555	    Ok(order)
556	}
