558	fn pseudo_peripheral_start(seed: usize, neighbors: &[Vec<usize>], degrees: &[usize]) -> usize {
559	    let component = bfs_reachable(seed, neighbors);
560	    let mut candidate = min_by_degree_then_index(&component, degrees).unwrap_or(seed);
561	
562	    let (mut candidate_eccentricity, mut last_level) = bfs_eccentricity(candidate, neighbors);
563	    loop {
564	        let next = match min_by_degree_then_index(&last_level, degrees) {
565	            Some(node) => node,
566	            None => break,
567	        };
568	        let (next_eccentricity, next_last_level) = bfs_eccentricity(next, neighbors);
569	        if next_eccentricity > candidate_eccentricity {
570	            candidate = next;
571	            candidate_eccentricity = next_eccentricity;
572	            last_level = next_last_level;
573	        } else {
574	            break;
575	        }
576	    }
577	    candidate
578	}
