580	fn bfs_reachable(seed: usize, neighbors: &[Vec<usize>]) -> Vec<usize> {
581	    let mut marked = vec![false; neighbors.len()];
582	    marked[seed] = true;
583	    let mut reachable = vec![seed];
584	    let mut queue = VecDeque::new();
585	    queue.push_back(seed);
586	    while let Some(node) = queue.pop_front() {
587	        for &next in &neighbors[node] {
588	            if !marked[next] {
589	                marked[next] = true;
590	                reachable.push(next);
591	                queue.push_back(next);
592	            }
593	        }
594	    }
595	    reachable
596	}
