598	fn bfs_eccentricity(start: usize, neighbors: &[Vec<usize>]) -> (usize, Vec<usize>) {
599	    let mut marked = vec![false; neighbors.len()];
600	    marked[start] = true;
601	    let mut eccentricity = 0usize;
602	    let mut current_level = vec![start];
603	    let mut last_level = vec![start];
604	    loop {
605	        let mut next_level = Vec::new();
606	        for &node in &current_level {
607	            for &next in &neighbors[node] {
608	                if !marked[next] {
609	                    marked[next] = true;
610	                    next_level.push(next);
611	                }
612	            }
613	        }
614	        if next_level.is_empty() {
615	            break;
616	        }
617	        eccentricity += 1;
618	        last_level = next_level.clone();
619	        current_level = next_level;
620	    }
621	    (eccentricity, last_level)
622	}
