3469	            Some(k) => k,
3470	            None => {
3471	                groups.push((
3472	                    identity,
3473	                    prepare_group(source).map(Arc::new),
3474	                    GroupCache::default(),
3475	                ));
3476	                groups.len() - 1
3477	            }
3478	        };
3479	        let (_, group, cache) = &mut groups[index];
3480	        let group = match group {
3481	            Ok(g) => g.clone(),
