491	/// The canonical retained-state encoding (D1 §4.1.8: "the canonical limbs of
492	/// u_p and every member's Q"; ROOT's K4 ruling Q10): p, L, then u for every
493	/// DOF ascending and every member's Q (id order), each as K3's `parts()` with
494	/// a zero's sign normalized to +.
495	pub(crate) fn state_encoding<const L: usize>(p: u32, u: &[Wide<L>], q: &[[Wide<L>; 6]]) -> Vec<u8>
496	where
497	    Wide<L>: SupportedWidth,
498	{
499	    let mut out = b"K4RST\x01".to_vec();
500	    put_u32(&mut out, p);
501	    put_u32(&mut out, L as u32);
502	    let value = |out: &mut Vec<u8>, w: &Wide<L>| {
503	        let (negative, exponent, significand) = w.parts();
504	        out.push(u8::from(negative && !w.is_zero()));
505	        put_i64(out, exponent);
506	        for limb in significand {
507	            put_u64(out, limb);
508	        }
509	    };
510	    put_u32(&mut out, u.len() as u32);
511	    for w in u {
512	        value(&mut out, w);
513	    }
514	    put_u32(&mut out, q.len() as u32);
515	    for member in q {
516	        for w in member {
517	            value(&mut out, w);
518	        }
519	    }
520	    out
521	}
