 66	/// The connected components of the free–free structural pattern.
 67	#[derive(Debug, Clone, PartialEq, Eq)]
 68	pub(crate) struct FreeBlocks {
 69	    /// The block of each free position.
 70	    pub(crate) of: Vec<u32>,
 71	    /// The free positions of each block, ascending; blocks are numbered by
 72	    /// their least free position.
 73	    pub(crate) positions: Vec<Vec<usize>>,
 74	    /// The body of each block (blocks refine bodies).
 75	    pub(crate) body: Vec<u32>,
 76	}
 77	
 78	impl FreeBlocks {
 79	    pub(crate) fn len(&self) -> usize {
 80	        self.positions.len()
 81	    }
 82	}
 83	
 84	pub(crate) fn free_blocks(
 85	    source: &PrimitiveSource,
 86	    structure: &Structure,
 87	    ordering: &Ordering,
 88	) -> FreeBlocks {
 89	    let n = ordering.free.len();
 90	    let mut of = vec![u32::MAX; n];
 91	    let mut positions: Vec<Vec<usize>> = Vec::new();
 92	    for start in 0..n {
 93	        if of[start] != u32::MAX {
 94	            continue;
 95	        }
 96	        let id = positions.len() as u32;
 97	        of[start] = id;
 98	        let mut stack = vec![start];
 99	        let mut component = Vec::new();
100	        while let Some(a) = stack.pop() {
101	            component.push(a);
102	            for index in structure.pattern.row_range(ordering.free[a]) {
103	                let b = ordering.position[structure.pattern.column(index)];
104	                if b != usize::MAX && of[b] == u32::MAX {
105	                    of[b] = id;
106	                    stack.push(b);
107	                }
108	            }
109	        }
110	        component.sort_unstable();
111	        positions.push(component);
112	    }
113	    let body = positions
114	        .iter()
115	        .map(|p| source.body_of_node((ordering.free[p[0]] / DOF_PER_NODE) as u32))
116	        .collect();
117	    FreeBlocks {
118	        of,
119	        positions,
120	        body,
121	    }
122	}
