124	/// 7a's data flag of every block, at a state u (all DOFs).
125	/// `prescribed_nonzero[g]`: whether constrained DOF g's exact prescribed value
126	/// is nonzero.
127	pub(crate) fn data_blocks<const L: usize>(
128	    blocks: &FreeBlocks,
129	    ordering: &Ordering,
130	    structure: &Structure,
131	    ledger: &RetainedLedger,
132	    prescribed_nonzero: &[bool],
133	    u: &[Wide<L>],
134	) -> Vec<bool>
135	where
136	    Wide<L>: SupportedWidth,
137	{
138	    let mut data = vec![false; blocks.len()];
139	    for (a, &g) in ordering.free.iter().enumerate() {
140	        let b = blocks.of[a] as usize;
141	        if data[b] {
142	            continue;
143	        }
144	        if ledger.has_nonzero_term(g) || !u[g].is_zero() {
145	            data[b] = true;
146	            continue;
147	        }
148	        for index in structure.pattern.row_range(g) {
149	            let c = structure.pattern.column(index);
150	            if ordering.position[c] == usize::MAX && prescribed_nonzero[c] {
151	                data[b] = true;
152	                break;
153	            }
154	        }
155	    }
156	    data
157	}
