161	/// Per block, the largest ratio ‖(K̃⁻¹x)_c‖₁/‖x_c‖₁ over the condition
162	/// screen's solves with x_c ≠ 0.
163	#[derive(Debug, Clone)]
164	pub(crate) struct BlockRatios<const L: usize>
165	where
165	where
166	    Wide<L>: SupportedWidth,
167	{
168	    positions: Vec<Vec<usize>>,
169	    est: Vec<Wide<L>>,
170	}
171	
172	impl<const L: usize> BlockRatios<L>
173	where
174	    Wide<L>: SupportedWidth,
175	{
176	    pub(crate) fn new(blocks: &FreeBlocks) -> Self {
177	        Self {
178	            positions: blocks.positions.clone(),
179	            est: vec![Wide::<L>::ZERO; blocks.len()],
180	        }
181	    }
182	
183	    /// After one screen solve y = K̃⁻¹x (both in free-position order).
184	    pub(crate) fn offer(
185	        &mut self,
186	        ctx: &mut WideContext<L>,
187	        sum: &mut ExactWideSum,
188	        x: &[Wide<L>],
189	        y: &[Wide<L>],
190	    ) -> Result<(), AttemptStop> {
191	        for (b, positions) in self.positions.iter().enumerate() {
192	            sum.clear();
193	            for &a in positions {
194	                sum.add_wide(&x[a].abs(), false)?;
195	            }
196	            let xs = sum.round(ctx)?;
197	            if xs.is_zero() {
198	                continue;
199	            }
200	            sum.clear();
201	            for &a in positions {
202	                sum.add_wide(&y[a].abs(), false)?;
203	            }
204	            let ys = sum.round(ctx)?;
205	            let ratio = ctx.div(&ys, &xs)?;
206	            if ratio.cmp_value(&self.est[b]) == CmpOrdering::Greater {
207	                self.est[b] = ratio;
208	            }
209	        }
210	        Ok(())
211	    }
212	
213	    pub(crate) fn estimates(self) -> Vec<Wide<L>> {
214	        self.est
215	    }
216	}
