256	/// A block's first refusal (amendment A2): its kind, its pass and the
257	/// elimination row (`usize::MAX` for a per-block step).
258	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
259	pub struct BoundRefusal {
370	    block_of_row: &[u32],
371	    refused: &mut [Option<BoundRefusal>],
372	) -> Result<Vec<Wide<L>>, AttemptStop>
373	where
374	    Wide<L>: SupportedWidth,
375	{
376	    let n = f.rows();
377	    let one = Wide::<L>::ONE;
378	    let mut a = vec![one; n];
379	    for i in 0..n {
380	        let b = block_of_row[i] as usize;
381	        if refused[b].is_none() {
382	            let mut acc = Some(one);
383	            for j in f.first_of(i)..i {
384	                let l = f.entry(i, j).abs();
385	                if l.is_zero() {
386	                    continue;
387	                }
388	                let Some(t) = refusable(
389	                    mul_toward(ctx, sum, &l, &a[j], Toward::Up),
390	                    sum,
391	                    &mut refused[b],
392	                    BoundPass::Forward,
393	                    i,
394	                )?
395	                else {
396	                    acc = None;
397	                    break;
398	                };
399	                let Some(v) = refusable(
400	                    add_toward(ctx, sum, &acc.unwrap_or(one), &t, Toward::Up),
401	                    sum,
402	                    &mut refused[b],
403	                    BoundPass::Forward,
404	                    i,
405	                )?
406	                else {
407	                    acc = None;
408	                    break;
409	                };
410	                acc = Some(v);
411	            }
412	            if let Some(v) = acc {
413	                a[i] = v;
414	            }
415	        }
416	        guard.check(ctx, sum)?;
417	    }
418	    let mut c = Vec::with_capacity(n);
419	    for (i, ai) in a.iter().enumerate() {
420	        let b = block_of_row[i] as usize;
421	        let v = if refused[b].is_none() {
422	            refusable(
423	                div_toward(ctx, sum, ai, &f.entry(i, i), Toward::Up),
424	                sum,
425	                &mut refused[b],
426	                BoundPass::Pivot,
427	                i,
428	            )?
429	        } else {
430	            None
431	        };
432	        c.push(v.unwrap_or(Wide::<L>::ZERO));
433	    }
434	    for i in (0..n).rev() {
435	        let b = block_of_row[i] as usize;
436	        if refused[b].is_none() {
437	            let ci = c[i];
438	            for j in f.first_of(i)..i {
439	                let l = f.entry(i, j).abs();
440	                if l.is_zero() {
441	                    continue;
442	                }
443	                let Some(t) = refusable(
444	                    mul_toward(ctx, sum, &l, &ci, Toward::Up),
445	                    sum,
446	                    &mut refused[b],
447	                    BoundPass::Backward,
448	                    j,
449	                )?
450	                else {
451	                    break;
452	                };
453	                let Some(v) = refusable(
454	                    add_toward(ctx, sum, &c[j], &t, Toward::Up),
455	                    sum,
456	                    &mut refused[b],
457	                    BoundPass::Backward,
458	                    j,
459	                )?
460	                else {
461	                    break;
462	                };
463	                c[j] = v;
464	            }
465	        }
466	        guard.check(ctx, sum)?;
467	    }
468	    Ok(c)
469	}
