 80	/// E_q for every force or moment row of `layout` (None for the other rows),
 81	/// with the nonnegative operand w at every DOF (module documentation). The
 82	/// ledger enters the reactions when given.
 83	#[allow(clippy::too_many_arguments)]
 84	pub(crate) fn formation_scale<const L: usize>(
 85	    ctx: &mut WideContext<L>,
 86	    sum: &mut ExactWideSum,
 87	    guard: &StageGuard,
 88	    source: &PrimitiveSource,
 89	    layout: &[QuantityMeta],
 90	    structure: &Structure,
 91	    abar: &[Wide<L>],
 92	    members: &[MemberOperators<L>],
 93	    directional: &[DirectionalBlock<L>],
 94	    ledger: Option<&RetainedLedger>,
 95	    w: &[Wide<L>],
 96	    rounding: StageRounding,
 97	) -> Result<Vec<Option<Wide<L>>>, AttemptStop>
 98	where
 99	    Wide<L>: SupportedWidth,
100	{
101	    let zero = Wide::<L>::ZERO;
102	    let mut out: Vec<Option<Wide<L>>> = Vec::with_capacity(layout.len());
103	    // Displacements and node magnitudes carry no E.
104	    out.resize(source.dof_count() + source.node_count(), None);
105	    // Members: the end actions.
106	    let mut q_all: Vec<[Wide<L>; 6]> = Vec::with_capacity(members.len());
107	    let mut actions_all: Vec<[Wide<L>; 12]> = Vec::with_capacity(members.len());
108	    for m in members {
109	        let dofs = m.dofs();
110	        // d̄ per block (tr_i, rot_i, tr_j, rot_j).
111	        let mut block = [zero; 4];
112	        for (b, value) in block.iter_mut().enumerate() {
113	            sum.clear();
114	            for c in 0..3 {
115	                sum.add_wide(&w[dofs[3 * b + c]], false)?;
116	            }
117	            *value = stage(ctx, sum, rounding)?;
118	        }
119	        let d = |index: usize| block[index / 3];
120	        let inv = m.inv_length.abs();
121	        let mut e = [zero; 6];
122	        for (index, (plus, minus)) in [(6usize, 0usize), (9, 3)].into_iter().enumerate() {
123	            sum.clear();
124	            sum.add_wide(&d(plus), false)?;
125	            sum.add_wide(&d(minus), false)?;
126	            e[index] = stage(ctx, sum, rounding)?;
127	        }
128	        for (index, rotation, transverse) in
129	            [(2usize, 5usize, 1usize), (3, 11, 1), (4, 4, 2), (5, 10, 2)]
130	        {
131	            sum.clear();
132	            sum.add_wide(&d(rotation), false)?;
133	            sum.add_product(ctx, &inv, &d(transverse), false)?;
134	            sum.add_product(ctx, &inv, &d(transverse + 6), false)?;
135	            e[index] = stage(ctx, sum, rounding)?;
136	        }
137	        let (bz, by) = (m.bend_z.abs(), m.bend_y.abs());
138	        let (four_z, two_z) = (bz.mul_pow2(2)?, bz.mul_pow2(1)?);
139	        let (four_y, two_y) = (by.mul_pow2(2)?, by.mul_pow2(1)?);
140	        let mut q = [zero; 6];
141	        for (index, terms) in [
142	            [(m.axial.abs(), 0usize), (zero, 0)],
143	            [(m.torsion.abs(), 1), (zero, 1)],
144	            [(four_z, 2), (two_z, 3)],
145	            [(two_z, 2), (four_z, 3)],
146	            [(four_y, 4), (two_y, 5)],
147	            [(two_y, 4), (four_y, 5)],
148	        ]
149	        .into_iter()
150	        .enumerate()
151	        {
152	            sum.clear();
153	            for (coefficient, at) in terms {
154	                sum.add_product(ctx, &coefficient, &e[at], false)?;
155	            }
156	            q[index] = stage(ctx, sum, rounding)?;
157	        }
158	        let mut shear = |a: &Wide<L>, b: &Wide<L>| -> Result<Wide<L>, AttemptStop> {
159	            sum.clear();
160	            sum.add_product(ctx, &inv, a, false)?;
161	            sum.add_product(ctx, &inv, b, false)?;
162	            stage(ctx, sum, rounding)
163	        };
164	        let vy = shear(&q[2], &q[3])?;
165	        let vz = shear(&q[4], &q[5])?;
166	        let g = i64::from(m.g_exp);
167	        let raw = [
168	            q[0], vy, vz, q[1], q[4], q[2], q[0], vy, vz, q[1], q[5], q[3],
169	        ];
170	        let mut actions = [zero; 12];
171	        for (a, r) in actions.iter_mut().zip(raw) {
172	            *a = r.mul_pow2(g)?;
173	        }
174	        q_all.push(q);
175	        actions_all.push(actions);
176	        guard.check(ctx, sum)?;
177	    }
178	    for actions in &actions_all {
179	        out.extend(actions.iter().map(|a| Some(*a)));
180	    }
181	    // Stations.
182	    for s in source.stations() {
183	        let index = source.member_index(s.member).unwrap();
184	        let q = &q_all[index];
185	        let actions = &actions_all[index];
186	        let g = i64::from(members[index].g_exp);
187	        let t = Wide::<L>::from_f64(s.fraction)?.abs();
188	        let mut moment = |at_j: &Wide<L>, at_i: &Wide<L>| -> Result<Wide<L>, AttemptStop> {
189	            sum.clear();
190	            sum.add_product(ctx, &t, at_j, false)?;
191	            sum.add_product(ctx, &t, at_i, false)?;
192	            sum.add_wide(at_i, false)?;
193	            Ok(stage(ctx, sum, rounding)?.mul_pow2(g)?)
194	        };
195	        let my = moment(&q[5], &q[4])?;
196	        let mz = moment(&q[3], &q[2])?;
197	        for v in [actions[6], actions[7], actions[8], actions[9], my, mz] {
198	            out.push(Some(v));
199	        }
200	    }
201	    // Spring actions.
202	    let mut spring_e = Vec::with_capacity(source.springs().len());
203	    for s in source.springs() {
204	        sum.clear();
205	        let k = Wide::<L>::from_f64(s.stiffness)?.abs();
206	        sum.add_product(ctx, &k, &w[s.dof.global()], false)?;
207	        let v = stage(ctx, sum, rounding)?;
208	        spring_e.push(v);
209	        out.push(Some(v));
210	    }
211	    // Directional spring actions.
