637	/// K^c's contributions to row g (free), times u⁰ (exact at prescribed DOFs),
638	/// subtracted from `r` (item 1): r_g = f_g − Σ k·u⁰. With `delta`, instead
639	/// subtracts Σ_j K^c_gj·δ̂_j over the free columns (item 5's second part).
640	#[allow(clippy::too_many_arguments)]
641	fn contribution_products<const L: usize, const W: usize>(
642	    ctx_w: &mut WideContext<W>,
643	    r: &mut ExactWideSum,
644	    structure: &Structure,
645	    source: &PrimitiveSource,
646	    vs_ke: &[[[Wide<W>; 12]; 12]],
647	    vs_dir: &[[[Wide<W>; 3]; 3]],
648	    ordering: &Ordering,
649	    g: usize,
650	    free_values: &[Wide<L>],
651	    prescribed: Option<&[Vec<Wide<W>>]>,
652	) -> Result<(), AttemptStop>
653	where
654	    Wide<L>: SupportedWidth,
655	    Wide<W>: SupportedWidth,
656	{
657	    for index in structure.pattern.row_range(g) {
658	        let j = structure.pattern.column(index);
659	        let position = ordering.position[j];
660	        let operands: Vec<Wide<W>> = if position != usize::MAX {
661	            let v = free_values[position];
662	            if v.is_zero() {
663	                continue;
664	            }
665	            vec![v.widen::<W>()]
666	        } else {
667	            match prescribed {
668	                Some(terms) => terms[j].clone(),
669	                None => continue,
670	            }
671	        };
672	        if operands.is_empty() {
673	            continue;
674	        }
675	        let upper = if g <= j {
676	            index
677	        } else {
678	            structure.pattern.transpose(index)
679	        };
680	        for item in structure.contributions(upper) {
681	            let k = match *item {
682	                Contribution::Member { member, a, b } => {
683	                    vs_ke[member as usize][a as usize][b as usize]
684	                }
685	                Contribution::Spring { spring } => {
686	                    Wide::<W>::from_f64(source.springs()[spring as usize].stiffness)?
687	                }
688	                Contribution::Directional { spring, a, b } => {
689	                    vs_dir[spring as usize][a as usize][b as usize]
690	                }
691	            };
692	            if k.is_zero() {
693	                continue;
694	            }
695	            for u in &operands {
696	                r.add_product(ctx_w, &k, u, true)?;
697	            }
698	        }
699	    }
700	    Ok(())
701	}
