105	/// D1 §4.1.6.1 item 5: L_b from the body's node coordinates.
106	pub fn body_extent(nodes: &[[f64; 3]]) -> f64 {
107	    let mut d = [0.0f64; 3];
108	    for (a, slot) in d.iter_mut().enumerate() {
109	        let hi = nodes.iter().map(|p| p[a]).fold(f64::NEG_INFINITY, f64::max);
110	        let lo = nodes.iter().map(|p| p[a]).fold(f64::INFINITY, f64::min);
111	        *slot = hi - lo;
112	    }
113	    (d[0] * d[0] + d[1] * d[1] + d[2] * d[2]).sqrt()
114	}
115	
116	/// D1 §4.1.6.1 item 6, in its order.
117	pub fn couple(s: [f64; 4], extent: f64) -> [f64; 4] {
118	    let [s_tr, s_ro, s_fo, s_mo] = s;
119	    if extent == 0.0 {
120	        return s;
121	    }
122	    [
123	        s_tr.max(extent * s_ro),
124	        s_ro.max(s_tr / extent),
125	        s_fo.max(s_mo / extent),
126	        s_mo.max(extent * s_fo),
127	    ]
128	}
