 15	/// What the kernel published for a row.
 16	#[derive(Clone, Debug, PartialEq)]
 17	pub enum Observed {
 18	    /// A binary64 value (an `Underflow` row is observed as its rounding, ±0).
 19	    Value(f64),
 20	    /// The two components of a bending magnitude.
 21	    Magnitude(f64, f64),
 22	    /// No row by construction (plan §4.2).
 23	    StructuralZero,
 24	    /// Nothing comparable was published (missing, or overflowed).
 25	    Unavailable(String),
 26	}
