 28	#[derive(Clone, Debug, PartialEq)]
 29	pub enum Verdict {
 30	    Pass,
 31	    Fail(String),
 32	    NotCovered { predicate_held: bool },
 33	    PassAbsoluteRange,
 34	    StructuralZero,
 35	    ExpectedUnresolved,
 36	}
