 38	fn holds(obs: &Observed, exp: &Exact, scale: &Exact) -> Option<bool> {
 39	    match obs {
 40	        Observed::Value(v) => Some(exact::predicate(&Exact::from_f64(*v), exp, scale)),
 41	        Observed::Magnitude(y, z) => Some(exact::magnitude_predicate(*y, *z, exp, scale)),
 42	        _ => None,
 43	    }
 44	}
 45	
 46	/// The verdict of one row: `covered` is the floor check's decision.
 47	pub fn judge(obs: &Observed, exp: &Exact, scale: &Exact, covered: bool) -> Verdict {
 48	    if *obs == Observed::StructuralZero {
 49	        return if exp.is_zero() {
 50	            Verdict::StructuralZero
 51	        } else {
 52	            Verdict::Fail("structural zero with a nonzero reference".into())
 53	        };
 54	    }
 55	    if !covered {
 56	        return Verdict::NotCovered {
 57	            predicate_held: holds(obs, exp, scale).unwrap_or(false),
 58	        };
 59	    }
 60	    match holds(obs, exp, scale) {
 61	        None => Verdict::Fail(match obs {
 62	            Observed::Unavailable(why) => why.clone(),
 63	            _ => unreachable!(),
 64	        }),
 65	        Some(true) if exact::outside_binary64(exp) => Verdict::PassAbsoluteRange,
 66	        Some(true) => Verdict::Pass,
 67	        Some(false) => Verdict::Fail("predicate".into()),
 68	    }
 69	}
