 66	    /// Parses a nonempty string of ASCII decimal digits.
 67	    pub fn from_decimal(digits: &str) -> Option<Self> {
 68	        if digits.is_empty() || !digits.bytes().all(|b| b.is_ascii_digit()) {
 69	            return None;
 70	        }
 71	        let mut n = Self::zero();
 72	        let bytes = digits.as_bytes();
 73	        let head = bytes.len() % 9;
 74	        let mut chunks: Vec<&[u8]> = Vec::new();
 75	        if head > 0 {
 76	            chunks.push(&bytes[..head]);
 77	        }
 78	        chunks.extend(bytes[head..].chunks(9));
 79	        for chunk in chunks {
 80	            let mut v = 0u32;
 81	            let mut scale = 1u32;
 82	            for &b in chunk {
 83	                v = v * 10 + u32::from(b - b'0');
 84	                scale *= 10;
 85	            }
 86	            n.mul_small(scale);
 87	            n.add_small(v);
 88	        }
 89	        Some(n)
 90	    }
 91	
 92	    fn mul_small(&mut self, m: u32) {
 93	        let mut carry = 0u64;
 94	        for l in &mut self.limbs {
 95	            let t = u64::from(*l) * u64::from(m) + carry;
 96	            *l = t as u32;
 97	            carry = t >> 32;
 98	        }
 99	        if carry > 0 {
100	            self.limbs.push(carry as u32);
101	        }
102	        self.trim();
103	    }
104	
105	    fn add_small(&mut self, a: u32) {
106	        let mut carry = u64::from(a);
107	        for l in &mut self.limbs {
108	            if carry == 0 {
109	                break;
110	            }
111	            let t = u64::from(*l) + carry;
112	            *l = t as u32;
113	            carry = t >> 32;
114	        }
115	        if carry > 0 {
116	            self.limbs.push(carry as u32);
117	        }
118	    }
119	
120	    /// self·2^k.
121	    pub fn shl(&self, k: u64) -> Self {
122	        if self.is_zero() {
123	            return Self::zero();
124	        }
125	        let words = (k / 32) as usize;
126	        let bits = (k % 32) as u32;
127	        let mut limbs = vec![0u32; words];
128	        if bits == 0 {
129	            limbs.extend_from_slice(&self.limbs);
130	        } else {
131	            let mut carry = 0u32;
132	            for &l in &self.limbs {
133	                limbs.push((l << bits) | carry);
134	                carry = l >> (32 - bits);
135	            }
136	            if carry > 0 {
137	                limbs.push(carry);
138	            }
139	        }
140	        let mut n = Self { limbs };
141	        n.trim();
142	        n
143	    }
144	
145	    /// self·10^k.
146	    pub fn mul_pow10(&self, mut k: u64) -> Self {
147	        let mut n = self.clone();
148	        while k >= 9 {
149	            n.mul_small(1_000_000_000);
150	            k -= 9;
151	        }
152	        if k > 0 {
153	            n.mul_small(10u32.pow(k as u32));
154	        }
155	        n
156	    }
