158	    pub fn add(&self, o: &Self) -> Self {
159	        let len = self.limbs.len().max(o.limbs.len());
160	        let mut limbs = Vec::with_capacity(len + 1);
161	        let mut carry = 0u64;
162	        for k in 0..len {
163	            let t = u64::from(*self.limbs.get(k).unwrap_or(&0))
164	                + u64::from(*o.limbs.get(k).unwrap_or(&0))
165	                + carry;
166	            limbs.push(t as u32);
167	            carry = t >> 32;
168	        }
169	        if carry > 0 {
170	            limbs.push(carry as u32);
171	        }
172	        let mut n = Self { limbs };
173	        n.trim();
174	        n
175	    }
