177	    /// self − o; requires self ≥ o.
178	    pub fn sub(&self, o: &Self) -> Self {
179	        assert!(self.cmp_nat(o) != Ordering::Less, "Nat::sub underflow");
180	        let mut limbs = Vec::with_capacity(self.limbs.len());
181	        let mut borrow = 0i64;
182	        for k in 0..self.limbs.len() {
183	            let mut t =
184	                i64::from(self.limbs[k]) - i64::from(*o.limbs.get(k).unwrap_or(&0)) - borrow;
185	            if t < 0 {
186	                t += 1 << 32;
187	                borrow = 1;
188	            } else {
189	                borrow = 0;
190	            }
191	            limbs.push(t as u32);
192	        }
193	        let mut n = Self { limbs };
194	        n.trim();
195	        n
196	    }
