198	    pub fn mul(&self, o: &Self) -> Self {
199	        if self.is_zero() || o.is_zero() {
200	            return Self::zero();
201	        }
202	        let mut acc = vec![0u64; self.limbs.len() + o.limbs.len() + 1];
203	        for (i, &a) in self.limbs.iter().enumerate() {
204	            let mut carry = 0u64;
205	            for (j, &b) in o.limbs.iter().enumerate() {
206	                let t = acc[i + j] + u64::from(a) * u64::from(b) + carry;
207	                acc[i + j] = t & 0xffff_ffff;
208	                carry = t >> 32;
209	            }
210	            let mut k = i + o.limbs.len();
211	            while carry > 0 {
212	                let t = acc[k] + carry;
213	                acc[k] = t & 0xffff_ffff;
214	                carry = t >> 32;
215	                k += 1;
216	            }
217	        }
218	        let mut n = Self {
219	            limbs: acc.into_iter().map(|v| v as u32).collect(),
220	        };
221	        n.trim();
222	        n
223	    }
