262	    /// A decimal string: an optional sign, digits with an optional point, and an
263	    /// optional exponent (`e`/`E`, optional sign). R1's `0`, `0.00000001`,
264	    /// `1e+80` and `-3.2913…e-2864` all parse exactly.
265	    pub fn parse_decimal(text: &str) -> Result<Self, String> {
266	        let err = || format!("not a decimal: {text:?}");
267	        let (negative, body) = match text.as_bytes().first() {
268	            Some(b'-') => (true, &text[1..]),
269	            Some(b'+') => (false, &text[1..]),
270	            _ => (false, text),
271	        };
272	        let (mantissa, exp10) = match body.find(['e', 'E']) {
273	            Some(k) => (&body[..k], body[k + 1..].parse::<i64>().map_err(|_| err())?),
274	            None => (body, 0),
275	        };
276	        let (int, frac) = match mantissa.find('.') {
277	            Some(k) => (&mantissa[..k], &mantissa[k + 1..]),
278	            None => (mantissa, ""),
279	        };
280	        if int.is_empty() && frac.is_empty() {
281	            return Err(err());
282	        }
283	        let digits = format!("{int}{frac}");
284	        let mant = Nat::from_decimal(&digits).ok_or_else(err)?;
285	        Ok(Self::new(negative, mant, 0, exp10 - frac.len() as i64))
286	    }
