288	    /// A finite binary64 value, exactly (±0 is zero).
289	    pub fn from_f64(x: f64) -> Self {
290	        assert!(x.is_finite(), "Exact::from_f64 of a non-finite value");
291	        let bits = x.to_bits();
292	        let biased = ((bits >> 52) & 0x7ff) as i64;
293	        let fraction = bits & ((1u64 << 52) - 1);
294	        let (m, e) = if biased == 0 {
295	            (fraction, -1074)
296	        } else {
297	            (fraction | (1u64 << 52), biased - 1075)
298	        };
299	        Self::new(x.is_sign_negative(), Nat::from_u64(m), e, 0)
300	    }
