328	    /// Both operands as signed integers over one common factor 2^A·10^B.
329	    fn align(a: &Self, b: &Self) -> ((bool, Nat), (bool, Nat), i64, i64) {
330	        let p2 = if a.is_zero() {
331	            b.p2
332	        } else if b.is_zero() {
333	            a.p2
334	        } else {
335	            a.p2.min(b.p2)
336	        };
337	        let p10 = if a.is_zero() {
338	            b.p10
339	        } else if b.is_zero() {
340	            a.p10
341	        } else {
342	            a.p10.min(b.p10)
343	        };
344	        let lift = |x: &Self| -> (bool, Nat) {
345	            if x.is_zero() {
346	                return (false, Nat::zero());
347	            }
348	            let m = x
349	                .mant
350	                .shl((x.p2 - p2) as u64)
351	                .mul_pow10((x.p10 - p10) as u64);
352	            (x.negative, m)
353	        };
354	        (lift(a), lift(b), p2, p10)
355	    }
