357	    pub fn cmp(&self, o: &Self) -> Ordering {
358	        let ((na, a), (nb, b), _, _) = Self::align(self, o);
359	        match (na, nb) {
360	            (false, true) => {
361	                if a.is_zero() && b.is_zero() {
362	                    Ordering::Equal
363	                } else {
364	                    Ordering::Greater
365	                }
366	            }
367	            (true, false) => {
368	                if a.is_zero() && b.is_zero() {
369	                    Ordering::Equal
370	                } else {
371	                    Ordering::Less
372	                }
373	            }
374	            (false, false) => a.cmp_nat(&b),
375	            (true, true) => b.cmp_nat(&a),
376	        }
377	    }
