440	fn decimal_digits(n: &Nat) -> String {
441	    if n.is_zero() {
442	        return "0".into();
443	    }
444	    let mut limbs = n.limbs.clone();
445	    let mut parts = Vec::new();
446	    while !limbs.is_empty() {
447	        let mut rem = 0u64;
448	        for l in limbs.iter_mut().rev() {
449	            let t = (rem << 32) | u64::from(*l);
450	            *l = (t / 1_000_000_000) as u32;
451	            rem = t % 1_000_000_000;
452	        }
453	        while limbs.last() == Some(&0) {
454	            limbs.pop();
455	        }
456	        parts.push(rem);
457	    }
458	    let mut out = parts.pop().unwrap().to_string();
459	    for p in parts.iter().rev() {
460	        out.push_str(&format!("{p:09}"));
461	    }
462	    out
463	}
