470	/// The unchanged predicate `|obs − exp| ≤ 1e-9·max(|exp|, scale)`, exactly.
471	pub fn predicate(obs: &Exact, exp: &Exact, scale: &Exact) -> bool {
472	    obs.sub(exp).abs().cmp(&tolerance(exp, scale)) != Ordering::Greater
