475	/// The predicate on a magnitude `√(my² + mz²)`, exactly, without forming the
476	/// square root (plan §6.2): with t = 10⁻⁹·max(|exp|, scale), it holds iff
477	/// `my² + mz² ≤ (exp + t)²` (and exp + t ≥ 0) and, where exp − t > 0,
478	/// `my² + mz² ≥ (exp − t)²`.
479	pub fn magnitude_predicate(my: f64, mz: f64, exp: &Exact, scale: &Exact) -> bool {
480	    let (y, z) = (Exact::from_f64(my), Exact::from_f64(mz));
481	    let s = y.mul(&y).add(&z.mul(&z));
482	    let t = tolerance(exp, scale);
483	    let upper = exp.add(&t);
484	    if upper.is_negative() || s.cmp(&upper.mul(&upper)) == Ordering::Greater {
485	        return false;
486	    }
487	    let lower = exp.sub(&t);
488	    if lower.is_negative() || lower.is_zero() {
489	        return true;
490	    }
491	    s.cmp(&lower.mul(&lower)) != Ordering::Less
492	}
