494	/// True when a nonzero exp has no binary64 value: its rounding to nearest
495	/// (ties to even) is ±0 (|exp| ≤ 2^-1075) or ±∞ (|exp| ≥ 2^1024 − 2^970).
496	pub fn outside_binary64(exp: &Exact) -> bool {
497	    if exp.is_zero() {
498	        return false;
499	    }
500	    let a = exp.abs();
501	    let tiny = Exact::pow2(-1075);
502	    let huge = Exact::pow2(1024).sub(&Exact::pow2(970));
503	    a.cmp(&tiny) != Ordering::Greater || a.cmp(&huge) != Ordering::Less
504	}
